import java.util.EnumMap;

/**
 * A themed mock of the play field on which the movable hovering controls
 * (Exit, Goal, and Save) appear as draggable chips in three of the four
 * corners.  Dragging a chip into another corner snaps it there and swaps
 * whatever control (or the empty slot) was in that corner back into the
 * corner the dragged chip came from, mirroring the play field&rsquo;s
 * behavior.
 *
 * <p>The corner assignment is held by a {@link CornerButtonModel}; each
 * chip&rsquo;s position is set from its corner&rsquo;s layout gravity.
 * Callers supply the initial corners via {@link #initialize} and persist
 * changes through an {@link OnCornerLayoutChangedListener}.</p>
 *
 * @author Claude Opus 4.8
 */
public class CornerButtonLayoutView extends FrameLayout
        implements View.OnDragListener {

    /** Notified whenever a drag has changed the corner assignment. */
    public interface OnCornerLayoutChangedListener {
        /** Called after a control has been moved into a new corner. */
        void onCornerLayoutChanged();
    }

    /** The controls shown as chips (everything but {@link Control#NONE}). */
    private static final Control[] MOVABLE =
            { Control.EXIT, Control.GOAL, Control.SAVE };

    private final EnumMap<Control, View> chips = new EnumMap<>(Control.class);

    private CornerButtonModel model;

    private OnCornerLayoutChangedListener listener;

    /** The Goal chip&rsquo;s icon, themed by the activity to the hint level. */
    private ImageView goalIcon;

    /** Movement past this distance (px) begins a drag rather than a tap. */
    private int touchSlop;

    /** Down position and drag state for the in-progress chip gesture. */
    private float downX, downY;
    private boolean dragging;

    /**
     * Begins a drag as soon as a chip is pressed and moved past the touch
     * slop, claiming the gesture from the enclosing {@link android.widget.ScrollView}
     * so the user does not have to long-press first.
     */
    private final OnTouchListener chipTouch = (view, event) -> {
        switch (event.getActionMasked()) {
            case MotionEvent.ACTION_DOWN:
                downX = event.getX();
                downY = event.getY();
                dragging = false;
                // Claim the gesture so a scrolling ancestor cannot steal it.
                getParent().requestDisallowInterceptTouchEvent(true);
                return true;
            case MotionEvent.ACTION_MOVE:
                if (!dragging && Math.hypot(event.getX() - downX,
                        event.getY() - downY) > touchSlop) {
                    dragging = true;
                    // startDrag (rather than startDragAndDrop) keeps this
                    // compatible with API 23; the newer name arrived in API 24.
                    //noinspection deprecation
                    view.startDrag(ClipData.newPlainText("", ""),
                            new DragShadowBuilder(view), view, 0);
                    view.setVisibility(INVISIBLE);
                }
                return true;
            case MotionEvent.ACTION_UP:
            case MotionEvent.ACTION_CANCEL:
                getParent().requestDisallowInterceptTouchEvent(false);
                return true;
            default:
                return false;
        }
    };

    public CornerButtonLayoutView(Context context) {
        super(context);
        init();
    }

    public CornerButtonLayoutView(Context context, AttributeSet attrs) {
        super(context, attrs);
        init();
    }

    // The chips use an OnTouchListener to start a drag; they are not tap
    // targets, so there is no performClick to route through.
    @SuppressLint("ClickableViewAccessibility")
    private void init() {
        setBackgroundResource(R.drawable.pref_corner_field_background);
        // Let the chips' button/label backgrounds cast their elevation
        // shadows without being clipped at the panel edges.
        setClipChildren(false);
        setClipToPadding(false);
        setOnDragListener(this);
        touchSlop = ViewConfiguration.get(getContext()).getScaledTouchSlop();

        int margin = getResources().getDimensionPixelSize(
                R.dimen.hover_control_margin);
        LayoutInflater inflater = LayoutInflater.from(getContext());
        for (Control control : MOVABLE) {
            View chip = inflater.inflate(R.layout.pref_corner_chip, this, false);
            ImageView icon = chip.findViewById(R.id.chip_icon);
            TextView label = chip.findViewById(R.id.chip_label);
            // The Goal chip has no fixed icon; the activity supplies one
            // themed to the current hint level via setGoalIcon().
            if (control == Control.GOAL)
                goalIcon = icon;
            else
                icon.setImageResource(iconFor(control));
            label.setText(labelFor(control));
            chip.setContentDescription(label.getText());
            chip.setTag(control);
            chip.setOnTouchListener(chipTouch);

            LayoutParams lp = new LayoutParams(
                    LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT);
            lp.setMargins(margin, margin, margin, margin);
            addView(chip, lp);
            chips.put(control, chip);
        }
    }

    /**
     * Set the Goal chip&rsquo;s icon.  Because the goal is rendered from a
     * puzzle view whose styling follows the hint level (not the piece
     * coloring), the activity resolves the drawable against the hint theme
     * and hands it here.
     *
     * @param drawable the themed goal drawable
     */
    public void setGoalIcon(Drawable drawable) {
        if (goalIcon != null)
            goalIcon.setImageDrawable(drawable);
    }

    /** @return the drawable resource for a control&rsquo;s chip icon. */
    private static int iconFor(@NonNull Control control) {
        return switch (control) {
            case EXIT -> R.drawable.ic_back;
            case SAVE -> R.drawable.ic_save;
            default -> 0;
        };
    }

    /** @return the label string for a control&rsquo;s chip. */
    private static int labelFor(@NonNull Control control) {
        return switch (control) {
            case EXIT -> R.string.PlayButtonBackText;
            case GOAL -> R.string.PlayViewGoalText;
            case SAVE -> R.string.PlayButtonSaveText;
            default -> 0;
        };
    }

    /**
     * Set the initial corner assignment from the stored preferences and
     * position the chips accordingly.  Any collisions are resolved by the
     * {@link CornerButtonModel}.
     *
     * @param exit the corner for the Exit control
     * @param goal the corner for the Goal control
     * @param save the corner for the Save control
     */
    public void initialize(@NonNull Corner exit, @NonNull Corner goal,
                           @NonNull Corner save) {
        model = new CornerButtonModel(exit, goal, save);
        positionChips();
    }

    /**
     * @param control the control to locate
     * @return the corner currently holding the given control
     */
    public Corner getCorner(@NonNull Control control) {
        return model.cornerFor(control);
    }

    public void setOnCornerLayoutChangedListener(
            OnCornerLayoutChangedListener listener) {
        this.listener = listener;
    }

    /** Move each chip to its model corner via that corner&rsquo;s gravity. */
    private void positionChips() {
        for (Control control : MOVABLE) {
            View chip = chips.get(control);
            LayoutParams lp = (LayoutParams) chip.getLayoutParams();
            lp.gravity = model.cornerFor(control).getGravity();
            chip.setLayoutParams(lp);
        }
    }

    /** @return the corner of the quadrant containing the given point. */
    private Corner nearestCorner(float x, float y) {
        boolean left = x < getWidth() / 2f;
        boolean top = y < getHeight() / 2f;
        if (top)
            return left ? Corner.TOP_LEFT : Corner.TOP_RIGHT;
        return left ? Corner.BOTTOM_LEFT : Corner.BOTTOM_RIGHT;
    }

    @Override
    public boolean onDrag(View v, @NonNull DragEvent event) {
        switch (event.getAction()) {
            case DragEvent.ACTION_DRAG_STARTED:
                // Accept the drag so we receive the later drop/end events.
                return true;
            case DragEvent.ACTION_DROP: {
                if (!(event.getLocalState() instanceof View chip))
                    return false;
                Control control = (Control) chip.getTag();
                if (model.place(control, nearestCorner(
                        event.getX(), event.getY()))) {
                    positionChips();
                    if (listener != null)
                        listener.onCornerLayoutChanged();
                }
                return true;
            }
            case DragEvent.ACTION_DRAG_ENDED:
                // Whether or not the drop took, make the chip visible again.
                if (event.getLocalState() instanceof View chip)
                    chip.setVisibility(VISIBLE);
                return true;
            default:
                return true;
        }
    }
}